-- Generated from PDF text extraction; source text is stored in nodes.content.
-- PostgreSQL schema: one row per source PDF, nodes stored as JSONB.
CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY, title TEXT NOT NULL, original_title TEXT, document_type TEXT NOT NULL, year_bs INTEGER NOT NULL, year_ad INTEGER NOT NULL, total_pages INTEGER NOT NULL, nodes JSONB NOT NULL, source_filename TEXT NOT NULL
);

INSERT INTO legal_documents (id,title,original_title,document_type,year_bs,year_ad,total_pages,nodes,source_filename) VALUES ($CODExc7db3ae21c$doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac$CODExc7db3ae21c$,$CODEx86d79cd3b1$The Electronic Transactions Act, 2063 (2008)$CODEx86d79cd3b1$,NULL,$CODEx76f3b5a717$act$CODEx76f3b5a717$,2063,2008,36,$CODExbe997d7b04$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "The Electronic Transactions Act, 2063 (2008)\nDate of Authentication and Publication\n22 Mansir 2063 ( december 8, 2006)\nAct number 27 of the year 2063\nAn Act promulgated for Electronic Transactions\nPreamble:\nWHEREAS, it is expedient to make, legal provisions for authentication and\nregularization of the recognition, validity, integrity and reliability of generation,\nproduction, processing, storage, communication and transmission system of electronic\nrecords by making the transactions to be carried out by means of electronic data\nexchange or by any other means of electronic communications, reliable and secured;\nAnd where as, for controlling the acts of unauthorized use of electronic records or of\nmaking alteration in such records through the illegal manner,\nNow, therefore, be it enacted by the House of Representatives in the First Year of the\nissuance of the Proclamation of the House of Representatives, 2063(2007) .", "children": []}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter - 1", "title": "Chapter - 1", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Short Title, Extension and Commencement: (1) This Act may be", "content": "called \"The Electronic Transactions act,2063 (2008)\".\n(2) This Act shall be deemed to have been commenced from 24 Bhadra\n2063 ( sep.2, 2006).\n(3) This Act shall extend throughout Nepal and shall also apply to\nany person residing anywhere by committing an offence in contravention to\nthis Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Definitions: Unless the subject or context otherwise requires, in this Act,-", "content": "1\n(a) \"Asymmetric Crypto System\" means a system that creates a secured\nkey-pair consisting of a private key creating a digital signature and a\npublic key to verify the digital signature.\n(b) \"License\" means a license obtained pursuant to Sub-section (3) of\nSection 18.\n(c) \"Originator\" means a person who generates, stores or transmits\nelectronic records, and this term also includes a person who causes any\nother person to carry out such functions:\nProvided that it shall not include an intermediary.\n(d) \"Computer\" means an electro-magnetic, optical or other high-speed data\nprocessing device or system, which performs logical, arithmetic and\nmemory functions by manipulating electro-magnetic or optical impulses,\nand also includes all acts of input, output, processing, storage and\ncomputer software or communication facilities which are connected or\nrelated to the computer in any computer system or computer network.\n(e) \"Computer Database\" means an information, knowledge and concept or\npresentation of instructions, which are being prepared or have already\nbeen prepared in word, image, voice or audio visual form in a\nformalized manner or which have been produced by a computer,\ncomputer system or computer network, with a view to use in a\ncomputer, computer system or computer network.\n(f) \"Computer Network\" means an interrelationship between two or more\nthan two computers having interconnection with each other or in contact\nof communication.\n(g) \"Computer System\" means a device or a group of devices, containing all\ncomputer programmes including input and output support devices,\nelectronic instructions, input and output data that performs logical,\narithmetic, data storage and retrieval, communication including\ncontrolling functions.\n2\n(h) \"Computer Resource\" means a computer, computer system, computer\nnetwork, data, computer database or software.\n(i) \"Subscriber\" means a person who has obtained a certificate under Sub-\nsection (3) of Section 31.\n(j) \"Key Pair\" means a private key in an asymmetric crypto system and of\npair of public key, interconnected in a mathematics form with the\nprivate key which has a code to verify digital signature by the public key\nto be created from the private key.\n(k) \"Data\" means the presentation of information, knowledge, fact and\nconcept or instructions in any form, which are kept in a formalized\nmanner in a computer system or computer network and is intended for\nprocessing the same, or processed or stored in a computer memory.\n(l) \"Tribunal\" means the Information Technology Tribunal formed pursuant\nto section 60.\n(m) \"Private Key\" means a key of any key pair used to create a digital\nsignature.\n(n) \"Controller\" means the Controller appointed or designated pursuant to\nsection 13.\n(o) \"Digital Signature\" means a signature made in any electronic form to be\nincluded in the transformation of electronic record by a person having a\nnon- transformed initial electronic record and the public key of signatory\nby using a type of asymmetric crypto system that may clearly ascertain\nthe following matters:\n(1) Whether or not transformation of electronic record was\ncreated by using a type of private key keeping a logical consistency with\nthe public key of signatory; and\n(2) Whether or not the initial electronic record has been\nchanged after the transformation of electronic record.\n3\n(p) \"Access\" means an opportunity of gaining entry into, logical,\narithmetical or resources of memory function of any computer,\ncomputer system or computer network, giving instructions to such\nresources or making communication contact with such resources.\n(q) \"Appellate Tribunal\" means the Information Technology Appellate\nTribunal formed pursuant to section 66.\n(r) \"Certificate\" means a Digital Signature Certificate issued by the\nCertifying Authority under Section 30.\n(s) \"Certification Practice Statement\" means any statement issued by a\nCertifying Authority to specify the practices to be applied by the\nCertifying Authority while issuing a Digital Signature Certificate.\n(t) \"Certifying Authority\" means a certifying authority which has obtained\na license to issue a Digital Signature Certificate under Sub-section (3) of\nSection 18.\n(u) \"Addressee\" means a person receiving the processed electronic record as\nintended by the originator.\nProvided that it shall not include an intermediary.\n(v) \"Electronic Record\" means the data, record, image or sound transmitted,\nreceived or stored in an electronic form by generating the same through\nany means.\n(w) \"Electronic Form\" means a form of information transmitted, received or\nstored by generating the same through the means of magnetic, optical,\ncomputer memory or similar other devices.\n(x) \"Public Key\" means a key of any key pair used to verify digital\nsignature.\n(y) \"Information\" means the data details of the scripted texts, images,\nsounds, codes, computer programmes, software and computer databases.\n4\n(z) \"Information system\" means a system to generate, produce, transmit,\nreceive, store and display information or to process the same by other\nmethod.\n(aa) Software\" means any specific part of computer system such as system\nsoftware and application software having the capacity for operating\ncomputer hardware.\n(ab) \"Computer Accessory\" means a technology such as computer resource,\nthe information used by any institution in its business, a software-like\nitem produced or purchased by such an institution, hardware and\ncomputer network.\n(ac) \"Government Authority\" means a Ministry, Secretariat, Department of\nGovernment of Nepal or the Offices thereunder, Constitutional Body or\nthe Offices thereunder, Court or Tribunal or Office of the Nepal Army\nand it shall also includes other Offices of the similar nature.\n(ad) \"Public Institution\" means the following institutions:-\n(1) A company, bank or board whether fully or partially owned or\ncontrolled by Government of Nepal , or a Commission agency,\nauthority, corporation, enterprise board, centre, council and other\ncorporate body of the similar nature established by Government\nof Nepal pursuant to the laws prevailing.\n(2) A university, school, research centre, and other similar academic\nor educational institutions operated by Government of Nepal or\nwhich have been receiving a full or partial grant from\nGovernment of Nepal,\n(3) The Local Bodies formed under the Local Self-Governance Act,\n1998 (2055 B.S);\n(4) The Institutions run on the loan, grant or guarantee of\nGovernment of Nepal;\n5\n(5) The Institution which is fully or partially owned or controlled by\nthe institution referred to in sub-Clauses (1), (2), (3) or (4) or\nwhich receiving grant from such institution;\n(6) Any other Institutions prescribed by Government of Nepal as a\npublic institution by a notification published in the Nepal\nGazette.\n(ae) “Prescribed” or “As prescribed” means prescribed or as prescribed in\nRules framed under this Act.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter - 2", "title": "Chapter - 2", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "3", "title": "Authencity of Electronic Record: (1) Any subscriber may, subject to the", "content": "provisions of this section, authenticate to any electronic record by his/her\npersonal digital signature.\n(2) While authenticating the electronic record pursuant to Sub-\nsection (1), an act of transforming such electronic record to other electronic\nrecord shall be effected by the use of asymmetric crypto system and hash\nfunction.\nExplanation: For the purpose of this section, \"hash function\" means the acts of\nmapping of algorithm or translating of a sequence of bits into another,\ngenerally smaller, set yielding the same hash result from any record in the same\nform while executing the algorithm each and every time by using the same\nrecord as an input, infeasible to derive or reconstruct any record from the hash\nresult produced by the algorithm from the computation point of view, and\nmaking the two records, which produce the same hash result by using the\nalgorithm, computationally infeasible to derive.\n(3) Any person may verify the electronic record by using the public\nkey of the subscriber.\n6", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Legal Recognition of Electronic Record: Where the prevailing law", "content": "requires any information, documents, records or any other matters to be kept in\nwritten or printed typewritten form, then, if such information, document, record\nor the matter is maintained in an electronic form by fulfilling the procedures as\nstipulated in this Act or the Rules made hereunder, such electronic record shall\nalso have legal validity.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Legal Recognition of Digital Signature: Where the prevailing law requires", "content": "any information, document, record or any other matters to be certified by\naffixing signature or any document to be signed by any person; then, if such\ninformation, documents, records or matters are certified by the digital signature\nafter fulfilling the procedures as stipulated in this Act or the Rules made\nhereunder, such digital signature shall also have legal validity.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Electronic Records to be Kept Safely: Where the prevailing law requires", "content": "any information, document or record to be kept safely for any specific period of\ntime and if such information, document or record are kept safely in an\nelectronic form, by fulfilling the following condition,, such information,\ndocument or record shall have legal validity if that is,-\n(a) kept in an accessible condition making available for a subsequent\nreference,\n(b) kept safely in the format that can be demonstrated subject to presenting\nagain exactly in the same format in which they were originally generated\nand transmitted or received or stored,\n(c) kept making the details available by which the origin, destination and\ntransmission or date and time of receipt can be identified,\nProvided that the provision of this Clause shall not be applied in regard to any\ninformation to be generated automatically for the purpose of transmitting or\nreceiving any record.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "7", "title": "Electronic Record May Fulfill the Requirement of Submission of any", "content": "Original Document: Where the prevailing law requires that any record shall\n7\nhave to be submitted or retained in its main or original form or kept safely,\nthen, such requirement shall, if the following terms are fulfilled, be deemed to\nhave been satisfied by the electronic records:\n(a) If there exits a ground as prescribed that can be believed that any type of\nchange is not made in such record by any means from the fist time of its\ngeneration in electronics form,\n(b) If such record is of the nature where there is a compulsion of submitting\nsuch document to any person it could be clearly shown to such a person\nto whom it requires to do so.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "Secured Electronic Records: If the verification has been made as prescribed", "content": "in connection with the matter as to whether or not any type of changes are\nmade into the electronic records generated with the application of security\nprocedures as prescribed, such electronic records shall be deemed to be a\nsecured electronic records.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "9", "title": "Secured Digital Signature: Where any digital signature made in electronic", "content": "record has been examined in a manner as prescribed with the application of\nsuch security procedure as prescribed, then, such digital signature shall be\ndeemed to be a secured digital signature.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter - 3", "title": "Chapter - 3", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "10", "title": "Electronic Record to be Attributed to Originator: (1) Any specific", "content": "electronic record shall, in case of any of the following conditions, be attributed\nto the originator:\n(a) If such an electronic record was transmitted by the originator\nhim/herself,\n8\n(b) If such an electronic record was transmitted by a person who had\nthe authority to act on behalf of the originator in respect of such\nan electronic record,\n(c) Such an electronic record was transmitted through any\ninformation system that was programmed by the originator or on\nbehalf of the originator to operate automatically.\n(2) If any condition exists as prescribed in respect of electronic\nrecord transmitted pursuant to Sub-section (1), the addressee shall assume that\nsuch an electronic record is attributed to any particular originator and shall\nhave the authority to act thereon accordingly.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "11", "title": "Procedure of Receipt and Acknowledgement of Electronic Record:", "content": "(1) Where the originator requests the addressee to transmit the\nacknowledgement or receipt of electronic record at the time of or before the\ndispatch of such electronic record or where there is an agreement between the\noriginator and addressee to transmit the acknowledgement or receipt of such an\nelectronic record, then, the provisions of Sub-sections (2), (3) and (4) shall be\napplied in relation to the receipt and acknowledgement of such an electronic\nrecord.\n(2) Where there is no agreement between the originator and\naddressee that information or acknowledgement of receipt of electronic record\nis to be given in a particular format or by a particular manner, such an\ninformation or receipt may be given as the following:-\n(a) by automated or any other means of communication by the\naddressee,\n(b) by any conduct of the addressee sufficient to indicate that the\noriginator has received electronic record.\n(3) Where the originator has stipulated in relation to any electronic\nrecord that such an electronic record shall be binding on him/her only after the\nreceipt of information or acknowledgement of receipt of such electronic record\n9\nfrom the addressee, then, unless the information or acknowledgement of receipt\nof such an electronic record has been so received from addressee, the electronic\nrecord shall not be deemed to have been transmitted by the originator.\n(4) Where the originator has not stipulated that the electronic record\nshall be binding only on receipt of such acknowledgement, and where the\noriginator and addressee have not agreed upon or have not specified any time\nfor acknowledgement of such receipt of electronic record, then, the originator\nshall have to receive such acknowledgement of receipt of such an electronic\nrecord from addressee within a specified time as prescribed. If such\nacknowledgement of receipt is not received from addressee, then, such an\nelectronic record shall be deemed to have not been transmitted by the\noriginator.\n(5) Other procedures of receipt of acknowledgement of electronic\nrecord shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "12", "title": "Time and Place of Dispatch and Receipt of Electronic Record: (1)", "content": "Save as otherwise agreed between the originator and the addressee, the dispatch\nof an electronic record occurs when it enters into an information system outside\nthe control of the originator.\n(2) Save as otherwise agreed between the originator and the\naddressee, the time of receipt of an electronic record shall be determined as\nprescribed.\n(3) Save as otherwise agreed between the originator and the\naddressee, an electronic record shall be deemed to have been dispatched from\nthe place where the originator has his/her place of business and shall be\ndeemed to have been received at the place where the addressee has his/her\nplace of business.\nExplanation: For the purpose of this Sub-section \"the place of business\"\nmeans:\n10\n(a) In case the originator or the addressee has more than one place of\nbusiness, the place of business means the place where the concerned\nbusiness shall be operated\n(b) If the originator or the addressee does not have a place of business, their\nplace of residence shall be considered their place of business.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 4", "title": "Chapter 4", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "13", "title": "Appointment of the Controller and other Employees: (1)", "content": "Government of Nepal may, by notification in the Nepal Gazette, designate any\nGovernment officer or appoint any person who has qualifications as\nprescribed in the office of the Controller.\n(2) Government of Nepal may, in order to assist the Controller\nto perform his/her functions to be performed under this Act, appoint or assign a\nDeputy Controller and other employees as required. The employees so\nappointed or assigned shall perform their functions under the general direction\nand control of the Controller.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "14", "title": "Functions, Duties and Powers of the Controller:", "content": "The functions, duties and powers of the controller shall be as follows:-\n(a) To issue a license to the certifying Authority,\n(b) To exercise the supervision and monitoring over the activities of\nCertifying Authority,\n(c) To fix the standards to be maintained by certifying authority in respect\nto the verification of digital signature,\n(d) To specify the conditions to be complied with by the certifying authority\nin operating his/her business,\n(e) To specify the format of the certificate and contents to be included\ntherein,\n11\n(f) To specify the procedures to be followed by the certifying authority\nwhile conducting his/her dealings with the subscribers,\n(g) To maintain a record of information disclosed by the certifying authority\nunder this act and to make provision of computer database accessible to\npublic and to update such database,\n(h) To perform such other functions as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "15", "title": "License to be obtained: No person shall perform or cause to be performed", "content": "the functions of a certifying authority without obtaining a license under this\nAct.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "16", "title": "Application to be submitted for a License: (1) Any person willing to", "content": "work as Certifying Authority by issuing a certificate under this Act and who\nhas the qualifications as prescribed shall have to submit an application to the\ncontroller in a format as prescribed accompanied by a fee as prescribed for\nobtaining a license for the certification.\n(2) The applicant applying under Sub-section (1) shall also attach the\nfollowing documents:\n(a) Details regarding certification,\n(b) Documents to prove the identification and verification of the\napplicant,\n(c) Statements specifying the financial resources, human resources and\nother necessary facilities,\n(d) Such other documents as prescribed.\n(3) The controller may, if he/she thinks necessary, ask the applicant\nto serve additional documents and details in connection to examine the\nappropriation of the applicant as to perform the function of Certifying\nAuthority. If the necessary additional documents and details are so asked, no\nactions shall be taken upon the application of the applicant unless he/she\nsubmits such documents and details.\n12", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "17", "title": "Other Functions and Duties of the Certifying Authority:", "content": "Other functions and duties of the certifying authority, other than those to\nissue a certificate, to suspend or revoke it, shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "18", "title": "Procedure for granting of a license: (1) The Controller may, on receipt of", "content": "an application under section 16, after considering the qualification of applicant\nand also the documents and statements decide upon within a period of two\nmonths of receipt of such application whether or not such a person possesses\nthe financial, physical and human resources, and other facilities as prescribed\nand whether or not a license should be issued to such an applicant and a notice\nto that effect shall be given to him.\n(2) While deciding upon the issuance of a license under Sub-section\n(1), the Controller may inspect the facilities, financial and physical resources of\nthe applicant.\n(3) If the Controller decides to issue a license under Sub-section (1),\na license in the prescribed format shall be issued to the applicant specifying the\nperiod of validity of the license and also the terms and conditions to be\nfollowed by him.\n(4) Other procedures relating to the issuance of a license shall be as\nprescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "19", "title": "Renewal of License: (1) A license obtained by Certifying Authority shall", "content": "have to renew in each year,\n(2) A Certifying Authority desirous to renew the license under Sub-\nsection (1), shall have to submit and application in the prescribed format to the\nController at least two months prior to the expiry of the period of validity of\nsuch a license along with such renewal fee as prescribed,\n(3) If an application is submitted for renewal, under Sub-section (2),\nthe Controller shall have to decide whether to renew the license or not, after\ncompleting the procedures as prescribed one month prior to the expiry date of\nvalidity of such a license,\n13\n(4) While deciding to reject to renew a license, the applicant shall be\ngiven a reasonable opportunity to present his/her statement in this regard.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "20", "title": "License may be suspended: (1) If the documents or statement and statement", "content": "of financial and physical resources submitted by the certifying authority before\nthe Controller in order to obtain a license are found incorrect or false or the\nconditions to be complied with in course of operation of business is not\ncomplied with or this Act of the Rules framed hereunder are found to be\nviolated, the Controller may suspend the license of the certifying authority till\nthe inquiry in this regard is completed.\nProvided that, Certifying Authority shall be given the reasonable\nopportunity to present his/her defense prior to such suspension of a license.\n(2) Other procedures concerning suspension of license and other\nprovisions related thereto be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "21", "title": "License may be revoked: (1) If the controller believes, after completion of", "content": "an inquiry in connection to any activity of Certifying Authority, made duly, as\nprescribed, that any of the following circumstances have been occurred, the\nController may revoke a license issued under this Act, at any time, as he deems\nto be appropriate:\n(a) If the Certifying Authority fails to comply with the liabilities under this\nact and the rules made thereunder.\n(b) If it is found that the Certifying Authority has submitted false or\nincorrect document or statement at the time of submitting an application\nfor obtaining a license or for its renewal, as the case may be.\n(c) If the Certifying Authority operates business in such a manner so that it\nshall make adverse effect to the public interest or to the national\neconomy,\n(d) If the Certifying Authority commits any act that is defined as an offence\nunder this Act or the Rules framed hereunder.\n14\n(2) The Controller shall, prior to revocation of a license under Sub-\nsection (1), provide a reasonable opportunity to the Certifying Authority to\npresent his/her defense.\n(3) Other procedures concerning revocation of a license shall be as\nprescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "22", "title": "Notice of Suspension or revocation of a License: (1) Where a license of", "content": "any Certifying Authority is suspended or revoked under Section 20 or 21, as\nthe case may be the Controller shall give a written notice to the Certifying\nAuthority of such suspension or revocation, as the case may be, to such a\ncertifying Authority and shall keep such a notice in his computer database and\nalso publish in the electronic form.\n(2) The Controller shall publish the notice of suspension or\nrevocation of a license at least in two daily newspapers in Nepali and English\nlanguages for two times.\nProvided that, there shall be no effect to any decision of suspension or\nrevocation, as the case may be, made by the Controller under Section 20 or 21,\nmerely on the ground of non-publication of such a notice.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "23", "title": "Recognition to Foreign Certifying Authority may be given: (1) The", "content": "Controller may with the prior approval of Government of Nepal, and subject to\nsuch conditions and restrictions as may be prescribed, by notification in the\nNepal Gazette, recognize any Certifying Authority who has obtained a license\nto certify under any foreign law. Any foreign Certifying Authority so\nrecognized may issue the certificates under this Act or the Rules made\nthereunder throughout the Nepal.\n(2) The procedures to be adopted in providing the recognition to a\nforeign Certifying Authority as referred to in Sub-section (1), shall be as\nprescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "24", "title": "The Controller may issue Orders: (1) The Controller may, in order to", "content": "cause to fulfill the responsibilities in regard to issuance of a certificate by the\n15\nCertifying Authorities, issue directives, from time to time. It shall be a duty of\nthe Certifying Authority to comply with such directives.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "25", "title": "The Controller may delegate power: The Controller may, in order to", "content": "perform the function to be performed by him/her delegate to any officer\nsubordinate to him/her to exercise all or any of his/her powers under this Act or\nthe Rules framed thereunder.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "26", "title": "The Controller may investigate: (1) The Controller may, if he/she", "content": "believes that this Act or the Rules framed hereunder are not complied with by\nthe Certifying Authority or by other concerned person, conduct him/herself or\ncause any officer to conduct necessary investigation in that regard.\n(2) It shall be a duty of Certifying Authority to assist the\ninvestigations, referred to in Sub-section (1).\n(3) The procedure to be followed by the Controller or any other\nofficer in respect to investigation referred to in Sub-section (1) shall be as\nprescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "27", "title": "Performance Audit of Certifying Authority: (1) The Controller may", "content": "conduct or cause to be conducted performance audit of the Certifying Authority\nin each year.\n(2) The Controller may, for the purpose of the performance audit\nreferred to in Sub-section (1), appoint any recognized auditor, who has\nexpertise in computer security or any computer expert.\n(3) The Controller shall publish the report of the performance audit\nin the electronic form made under Sub-section (1) by maintaining in his/her\ncomputer database.\n(4) The qualification of the performance auditor or remuneration and\nthe procedures of such audit shall be as prescribed.\n16\n(5) The Controller shall fix the standard of the service of Certifying\nAuthority and publish a notice thereof publicly for the information to the\npublic-in-general.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "28", "title": "The Controller to have the Access to Computers and data: (1) The", "content": "Controller shall, if there is a reasonable ground to suspect that provision of this\nAct and Rules framed hereunder has been violated, have the power to have the\naccess to any computer system, apparatus, devices, data, information system or\nany other materials connected with such system.\n(2) The Controller may, for the purpose of Sub-section (1), issue\nnecessary directives to the owner of any computer system, apparatus, device,\ndata, information system or any material connected with such system or to any\nother responsible person to provide technical or other cooperation as he/she\ndeems necessary.\n(3) It shall be the duty of the concerned person to comply with such\ndirective issued under Sub-section (2).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "29", "title": "Record to be maintained: (1) The Controller shall maintain records of all", "content": "Certificates issued under this Act.\n(2) The Controller shall, in order to ensure the privacy and security\nof the digital signatures, perform following functions:\n(a) To use Computer Security System,\n(b) To apply security procedures to ensure the privacy and\nintegrity of digital signature,\n(c) To comply with the standard as prescribed,\n(3) The Controller shall maintain and update computerized data base\nof all public keys in a computer system.\n(4) For the purpose of verification of Digital Signature, the\nController shall make available a public key to any person requesting for such a\nkey.\n17", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-5", "title": "Chapter-5", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "30", "title": "Certifying Authority may issue a Certificate: Only a licensed or", "content": "recognized Certifying Authority under this Act may issue a Digital Signature\nCertificate.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "31", "title": "Apply to obtain a Certificate: (1) Any person desirous to obtain Digital", "content": "Signature Certificate may apply to the Certifying Authority in such a format\nalong with such fee and other statements as prescribed.\n(2) On receipt of an application under Sub-section (1), the Certifying\nAuthority shall have to decide whether to issue or not a certificate to the\napplicant within one month of such application so received.\n(3) The Certifying Authority shall, if it decides to issue a certificate\nunder Sub-section (2), issue a Digital Signature Certificate within seven days\naffixing his signature in a prescribed format with the inclusion of such\nstatements as prescribe and if it decides to reject to issue such certificate, the\napplicant shall be notified the reasons for rejection within seven days.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "32", "title": "Certificate may be suspended: (1) Certifying Authority may suspend the", "content": "Certificate in following circumstances:\n(d) If the subscriber obtaining the certificate or any person\nauthorized to act on behalf of such a subscriber, requests to\nsuspend the certificate.\n(e) If it is found necessary to suspend the certificate that\ncontravenes public interest as prescribed.\n(f) If it is found that significant loss might be caused to those\npersons who depend on the certificate by the reason that\nprovisions of this Act or the Rules framed hereunder were\nnot followed at the time of issuance of the certificate, and if\n18\nthe controller instructs to suspend the certificate having\nspecified the above ground.\n(2) Grounds and procedures for suspension and release of the\nsuspended certificates shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "33", "title": "Certificate may be revoked: (1) The Controller or the Certifying Authority", "content": "may revoke a Certificate in following conditions:\n(g) Where the subscriber or any other person authorized by him\nrequests to revoke a certificate,\n(h) If it is necessary to revoke in a certificate that contravenes\nthe public interest as prescribed,\n(i) Upon the death of the subscriber,\n(j) Upon the insolvency, winding up or dissolution of the\ncompany or corporate body under the prevailing laws,\nwhere the subscriber is a company or a corporate body.\n(k) If it is proved that a requirement for issuance of the\nCertificate was not satisfied.\n(l) If a material fact represented in the certificate is proved to\nbe false.\n(m) If a key used to generate key pair or security system was\ncompromised in a manner that affects materially the\nCertificate's reliability.\n(2) The procedures to be followed by the Controller or Certifying\nAuthority with respect to revocation of a Certificate shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "34", "title": "Notice of Suspension or Revocation: (1) Where a Certificate is suspended", "content": "or revoked under sections 32 or 33, the Certifying Authority or the Controller,\nas the case may be, shall publish a public notice thereof maintaining its record\nin their repository.\n19\n(2) It shall be the responsibility of the Certifying Authority or the\nController, as the case may be, to communicate the subscribers as soon as\npossible on suspension or revocation Certificates.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-6", "title": "Chapter-6", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "35", "title": "To Generate Key pair: (1) Where any Certificate issued by the Certifying", "content": "Authority and accepted by subscriber, consisting of a public key which\ncorresponds to the key pair and to be listed in such Certificate and if such key\npair is supposed to be generated by the subscriber only, then the subscriber\nshall generate such key pair by applying the secured asymmetric crypto system.\n(2) Notwithstanding anything contained in Sub-section (1), if a\nCertifying Authority and the subscriber have concluded an agreement or the\nCertifying Authority has accepted any specific system regarding the security\nsystem to be used to generate the key pair, then, it shall be the duty of\nsubscriber to apply the security system as specified in agreement or accepted\nby the Certifying Authority.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "36", "title": "To Accept a Certificate: (1) The certificate shall be deemed to have been", "content": "accepted by the subscriber in the following conditions:\n(n) If he publishes such a certificate or authorizes to publish to\none or more persons, or\n(o) If there exists any ground of his acceptance to such\ncertificate which may cause to believe it.\n(2) If the certificate is accepted it shall be deemed that the subscriber,\nby that reason, has guaranteed to all who reasonably rely on the information\ncontained in the certificate that-\n(a) The subscriber holds the private key corresponding to the public\nkey and is entitled to hold the same,\n20\n(b) All representations and information made by the subscriber to the\nCertifying Authority in course of issuance of the certificate are\ntrue and correct and all facts relevant to the information\ncontained in the certificate are true, and\n(c) All information mentioned in the certificate is, to the best\nknowledge of subscriber, is true and correct.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "37", "title": "To retain the private key in a secured manner: (1) Every subscriber shall", "content": "exercise reasonable care to retain control of the private key corresponding to\nthe public key listed in the Certificate and adopt all measures to prevent its\ndisclosure to a person not authorized to affix the digital signature of subscriber.\n(2) If the private key has been disclosed or compromised by any\nreason whatsoever, then, the subscriber shall communicate the same without\nany delay to the Certifying Authority and on receipt of such information the\nCertifying Authority shall immediately suspend such a Certificate.\n(3) If a certificate is suspended under this Act, it shall be a duty of\nthe subscriber to retain the private key under this section in a safe manner\nthroughout the duration of such suspension of Certificate.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "38", "title": "To Deposit the Private Key to the Controller: (1) If the Controller", "content": "thinks, in order to protect the sovereignty or integrity of Nepal, to maintain the\nfriendly relations with friendly countries, to maintain the law and order, to\nprevent from committing of any offence under the laws prevailing, and or in\nother conditions as prescribed, necessary to issue an order to any subscriber to\ndeposit the private key to him/her specifying reason there for, such a subscriber\nshall immediately deposit the private key to the Controller.\n(2) The controller shall not inform any unauthorized person about the\nprivate key deposited as per sub section (1).\n21", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-7", "title": "Chapter-7", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "39", "title": "Government Documents may be published in electronic form: (1)", "content": "Government of Nepal may also publish ordinance, Act, Rules Bye-laws,\nFormation Orders or notifications or any other matters in the electronic form\nwhich are published in the Nepal Gazette under the prevailing laws.\n(2) Where the prevailing law provides for the filing of any form,\napplication or any other document or any record to be generated or retained or\nsecured and or any license or permit or approval or certificate to be issued or\nprovided or any payment to be made in any Government agency, or public\nentity or in any bank or financial institution operating business within the\nNepal, it may be filed, generated, retained or secured or issued or granted in\nelectronic form or payment may be made in electronic mode of\ncommunication, and, it shall not be denied to provide the legal validity to such\nform, application, document record, license, permit or approval, certificate or\npayment on the ground of the use of electronic form or electronic\ncommunication mode.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "40", "title": "To Accept the Document in Electronic Form: (1) Government agency", "content": "or public entity or bank or financial institutions operating business within the\nNepal may also accept any document and payment to be submitted or paid to\nthem under the prevailing law in electronic form or through any electronic\nmode and if such documents and submitted or payment is made, as the case\nmay be, it shall not be denied to grant legal recognition merely on the ground\nthat it was accepted electronic form or through any electronic mode.\n(2) Notwithstanding anything contained in Sub-section (1) no\nGovernment agency or public entity or bank of financial institution operating\nbusiness within the Nepal shall, except in the conditions as prescribed and\ngovernment agencies as prescribed, be compelled to accept any document or\n22\npayment in electronic form, and such an agency or institution shall, except in\nthe conditions and agency as prescribed, not compel to any other persons to\naccept any document in electronic form or the payment through any electronic\nform.\n(3) For the purpose of Sub-section (1), the provision relating to the\nprocedure, process and format to be followed shall as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "41", "title": "Use of Digital Signature in Government Offices: (1) Where it is", "content": "required that the concerned person shall have to affix his/her signature in any\ndocument or record for verification of such document or record to be\ntransmitted or issued by any Government agency or public entity or bank or\nfinancial institution operating business within the Nepal or to be accepted by\nsuch agency or institution then, Government of Nepal may, if it thinks\nappropriate, make a provision to use digital signature instead of such a\nsignature.\n(2) Notwithstanding anything contained elsewhere in this Act,\nGovernment of Nepal may, for the purpose of the provision made in Sub-\nsection (1), prescribe additional security procedure for the verification and\nauthentication of such digital signature.\n(3) Provisions regarding the Certifying Authority and Digital\nSignature Certificate to be used by the government agency or entity referred to\nin Sub-section (1), shall be as prescribed.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter –8", "title": "Chapter –8", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "42", "title": "Liability of Network Service Providers: Intermediaries providing their", "content": "services as network service providers shall undertake the following liabilities in\nregard to such service provided by them:\n(a) Liabilities referred to in the agreement made with the subscriber in\nregard to service provision,.\n23\n(b) Liabilities referred to in the license of network service providers, and,\n(c) Any such other liability as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "43", "title": "Network Service Provider not to be Liable: Notwithstanding anything", "content": "contained in Section 42, no network service provider shall be liable to bear any\ncriminal or civil liability arising from any fact or statement mentioned or\nincluded in the information or data of the third party made available in\nelectronic form by him/her merely on the ground that he/she has made\navailable the access to such information or data.\nProvided that, such a person or institution providing network service\nshall not be relieved from such liability, if he/she has made available access to\nsuch information or data with the knowledge that any fact or statement\nmentioned or included in such information or data contravene this Act or Rules\nframed hereunder.\nExplanation: For the purpose of this section\" Third Party\" means a net work\nservice provider who provides service as intermediary and any person over\nwhom there is no control of the network service provider.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -9", "title": "Chapter -9", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "44", "title": "To Pirate, Destroy or Alter computer source code: When computer", "content": "source code is required to be kept as it is position for the time being the\nprevailing law, if any person, knowingly or with malafide intention, pirates,\ndestroys, alters computer sources code to be used for any computer, computer\nprogramme, computer system or computer network or cause, other to do so,\nhe/she shall be liable to the punishment with imprisonment not exceeding three\nyears or with a fine not exceeding two hundred thousand Rupees or with both.\nExplanation: For the purpose of this section \"computer source code\" means\nthe listing of programmes, computer command, computer design and layout\nand programme analysis of the computer resource in any form.\n24", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "45", "title": "Unauthorized Access in Computer Materials: If any person with an", "content": "intention to have access in any programme, information or data of any\ncomputer, uses such a computer without authorization of the owner of or the\nperson responsible for such a computer or even in the case of authorization,\nperforms any act with an intention to have access in any programme,\ninformation or data contrary to from such authorization, such a person shall be\nliable to the punishment with the fine not exceeding Two Hundred Thousand\nRupees or with imprisonment not exceeding three years or with both depending\non the seriousness of the offence.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "46", "title": "Damage to any Computer and Information System: If any person", "content": "knowingly and with a mala fide intention to cause wrongful loss or damage to\nany institution destroys, damages, deletes, alters, disrupts any information of\nany computer source by any means or diminishes value and utility of such\ninformation or affects it injuriously or causes any person to carryout such an\nact, such a person shall be liable to the punishment with the fine not exceeding\ntwo thousand Rupees and with imprisonment not exceeding three years or with\nboth.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "47", "title": "Publication of illegal materials in electronic form: (1) If any person", "content": "publishes or displays any material in the electronic media including computer,\ninternet which are prohibited to publish or display by the prevailing law or\nwhich may be contrary to the public morality or decent behavior or any types\nof materials which may spread hate or jealousy against anyone or which may\njeopardize the harmonious relations subsisting among the peoples of various\ncastes, tribes and communities shall be liable to the punishment with the fine\nnot exceeding One Hundred Thousand Rupees or with the imprisonment not\nexceeding five years or with both.\n(2) If any person commit an offence referred to in Sub-section (1)\ntime to time he/she shall be liable to the punishment for each time with one and\none half percent of the punishment of the previous punishment.\n25", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "48", "title": "Confidentiality to Divulge: Save otherwise provided for in this Act or Rules", "content": "framed hereunder or for in the prevailing law, if any person who has an access\nin any record, book, register, correspondence, information, documents or any\nother material under the authority conferred under this Act or Rules framed\nhereunder divulges or causes to divulge confidentiality of such record, books,\nregisters, correspondence, information, documents or materials to any\nunauthorized person, he/she shall be liable to the punishment with a fine not\nexceeding Ten Thousands Rupees or with imprisonment not exceeding two\nyears or with both, depending on the degree of the offence.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "49", "title": "To inform False statement: If any person with an intention to obtain a", "content": "license from Certifying Authority under this Act or with any other intention\neither to Controller or with an intention to obtain Digital Signature Certificate\nor with any other intention conceals statement knowingly or lies any statement\nto be submitted to the Certifying Authority any false statements shall be liable\nto the punishment with a fine not exceeding One Hundred Thousands rupees\nor with an imprisonment not exceeding two years or with both.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "50", "title": "Submission or Display of False License or Certificates: (1) If any", "content": "person who works as a Certifying Authority without a license issued by the\nController under this Act, shall be liable to the punishment with a fine not\nexceeding one hundred thousands Rupees or with an imprisonment not\nexceeding two years or with both, depending on seriousness of the offence.\n(2) Any person without obtaining a license from the Certifying\nAuthority publishes a fake license or false statement in regard to license or\nprovides to any person by any other means, shall be liable to the punishment\nnot exceeding one hundred thousand Rupees in the case where the act referred\nto in Sub-section (1) has not been accomplished by such a person.\n(3) If any person publishes or otherwise makes available a certificate\nto any other person by any means knowingly that a certificate is not issued by\nthe Certifying Authority referred to in such a certificate or the subscriber listed\nin such certificate has not accepted the certificate or such a certificate is already\n26\nsuspended or revoked, shall be liable to the punishment with a fine not\nexceeding one hundred thousands Rupees or with an imprisonment not\nexceeding two years or with both.\nProvided that, if such a certificate suspended or revoked is published or\nprovided for the purpose of verification of the Digital Signature before it was\nsuspended or revoked, it shall not be deemed to have been committed an\noffence under this Sub-section.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "51", "title": "Non-submission of Prescribed Statements or Documents: (1) If any", "content": "person responsible to submit any statement, document or report to the\nController or Certifying Authority under this Act or Rules framed hereunder,\nfails to submit such statement, document, or report within the specified time\nlimit, such a person shall be liable to the punishment with a fine not exceeding\nfifty thousands Rupees.\n(2) Any person who fails to maintain duly any book, register, records\nor account and in a secured manner to be maintained duly and in a secured\nmanner under this Act or Rules framed hereunder shall be liable to the\npunishment with a fine not exceeding fifty thousands Rupees.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "52", "title": "To commit computer fraud: If any person, with an intention to commit any", "content": "fraud or any other illegal act, creates, publishes or otherwise provides digital\nsignature certificate or acquires benefit from the payment of any bill, balance\namount of any one's account, any inventory or ATM card in connivance of or\notherwise by committing any fraud, amount of the financial benefit so acquired\nshall be recovered from the offender and be given to the person concerned and\nsuch an offender shall be liable to the punishment with a fine not exceeding one\nhundred thousand Rupees or with an imprisonment not exceeding two years or\nwith both.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "53", "title": "Abetment to commit computer related offence: A person who abets", "content": "other to commit an offence relating to computer under this Act or who attempts\nor is involved in the conspiracy to commit such an offence shall be liable to the\n27\npunishment with a fine not exceeding fifty thousand Rupees or with\nimprisonment not exceeding six months or with both, depending on the degree\nof the offence.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "54", "title": "Punishment to the Accomplice: A person who assists others to commit", "content": "any offence under this Act or acts as accomplice, by any means shall be liable\nto one half of the punishment for which the principal is liable.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "55", "title": "Punishment in an offence committed outside Nepal: Notwithstanding", "content": "anything contained in the prevailing laws, if any person commits any act which\nconstitutes an offence under this Act and which involves the computer,\ncomputer system or computer network system located in Nepal, even though\nsuch an act is committed while residing outside Nepal, a case may be filed\nagainst such a person and shall be punished accordingly.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "56", "title": "Confiscation: Any computer, computer system, floppy, compact disks, tape", "content": "drivers, softwares or any other accessory devices used to commit any act\ndeemed to be an offence relating to computer under this Act shall be liable to\nconfiscation.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "57", "title": "Offences Committed by a corporate body: (1) If any act is done by a", "content": "corporate body which deems an offence under this Act, such an offence shall\nbe deemed to have been committed by a person who was responsible as chief\nfor the operation of the corporate body at the time of committing such an\noffence.\nProvided that, if the person who was responsible as a chief for the\noperation of such a corporate body proves that such an offence was committed\nwithout his/her knowledge or that he/she exercised all reasonable efforts to\nprevent such an offence, he/she shall not be liable to the guilty.\n(2) Notwithstanding anything contained in Sub-section (1), if it is\nproved that any offence under this Act committed by a corporate body with the\nconsent or in knowledge or by the reason of negligence of a director, manager,\nsecretary or any other responsible person of such corporate body, such an\n28\noffence shall be deemed to have been committed by such a corporate body and\nby a director, manager, secretary or other responsible person of such a\ncorporate body.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "58", "title": "Other Punishment: If any violation of this Act or Rules framed hereunder", "content": "has been committed, for which no penalty has been separately provided, such a\nviolator shall be liable to the punishment with a fine not exceeding fifty\nthousand Rupees, or with an imprisonment not exceeding six months or with\nboth.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "59", "title": "No Hindrance to Punish Under the Laws prevailing: If any act deemed to be", "content": "an offence under this Act shall also be deemed to be another offence under the\nlaws prevailing, it shall not be deemed to have been hindered by this Act to file\na separate case and punish accordingly.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-10", "title": "Chapter-10", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "60", "title": "Constitution of a Tribunal: (1) Government of Nepal shall, in order to", "content": "initiate the proceedings and adjudicate the offences concerning computer as\nreferred to in Chapter -9, constitute a three member Information Technology\nTribunal consisting of one member each of law, Information Technology and\nCommerce by notification in the Nepal Gazette from amongst the persons who\nare qualified under section 60.\n(2) The Law Member shall be the chairperson of the Tribunal.\n(3) The Tribunal shall exercise its jurisdiction as prescribed.\n(4) Any person aggrieved by an order or a decision made by Tribunal\nmay appeal to the Appellate Tribunal within thirty five days from the date of\nsuch order or decision, as the case may be.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "61", "title": "Qualification of the Member of the Tribunal: (1) Any person who has", "content": "the knowledge in information technology and, who is or who has been or who\n29\nis qualified to be a judge in the District Court, shall be eligible to be a law\nmember of the Tribunal.\n(2) A Nepalese citizen who holds at least master degree in computer\nscience or information technology and who has at least three years experience\nin the field of electronic transactions, information technology or electronic\ncommunication, shall be eligible to be a information technology member of the\nTribunal.\n(3) A Nepali citizen who holds at least master degree in management\nor commerce and who has specialization in the field of electronic transaction\nand who has at least three years experience in the related field shall be eligible\nto be a commerce member of the Tribunal.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "62", "title": "Terms of office, remuneration and conditions of service of the", "content": "Member of Tribunal: (1) The term of office of a member of the Tribunal\nshall be of five years and he/she shall be eligible for reappointment.\n(2) Remuneration and the terms and conditions of the service of a\nMember of the Tribunal shall as prescribed.\n(3) Every Member of the Tribunal shall, before assuming his/her\noffice, take the oath of his/her office and secrecy before the Chief Judge of\nAppellate Court in a format and in a manner as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "63", "title": "Circumstances under which office shall be fallen vacant and filling", "content": "up of vacancy: (1) Office of a Member of the Tribunal shall be fallen\nvacant in the following circumstances:\na) On expiry of terms of office,\nb) On attainment of sixty three years of age.\nc) On death,\nd) If one tenders resignation,\ne) If one is convicted by a court on any criminal offence involving\nmoral turpitude, or\n30\nf) If it is proved that one has misbehavior or has become\nincompetent to perform one's duty while making an inquiry by\nGovernment of Nepal on the charge that one has misbehavior\nagainst one's office or has become incompetent to perform one's\nduty.\nProvided that, a Member of the Tribunal charged under this\nClause shall given a reasonable opportunity to defense his/her case.\n(2) Notwithstanding anything contained in Clause (f), if the\nlaw member of the Tribunal is a sitting judge, while making such an\ninquiry, it shall be done in accordance with the prevailing law\nconcerning his/her terms of service.\n(3) The procedure of inquiry, for the purpose of Clause (f) of\nSub-section Sub-section (1), shall be as prescribed.\n(4) Government of Nepal shall, in case of vacancy of the\noffice of any member of Tribunal under Sub-section (1), fulfill such\nvacancy from among the persons who are qualified under section 61 for\nremaining term of office of such a member.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "64", "title": "Staff of the Tribunal: (1) Government of Nepal shall make available", "content": "necessary staff to the Tribunal to perform its functions.\n(2) Other provisions regarding the staff of the Tribunal shall be as\nprescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "65", "title": "Procedures to be followed by the Tribunal: The Tribunal shall, while", "content": "initiating proceedings and adjudicating the case under section 60, shall follow\nthe procedures as prescribed.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-11", "title": "Chapter-11", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "66", "title": "Establishment and formation of the Appellate Tribunal: (1)", "content": "Government of Nepal shall, in order to hear the appeal against the order or the\n31\ndecision made by the Tribunal and to hear the appeal against the decision or\norder made by the Controller or by the Certifying Authority, as the case may\nbe, under this Act, by notification in the Nepal Gazette, establish a three\nmember Information Technology Appellate Tribunal consisting of one member\neach of law, information technology and commerce from among the persons\nwho are qualified under section 67,\n(2) Law Member shall be the chairperson of the Appellate Tribunal.\n(3) Exercise of the jurisdiction of Appellate Tribunal shall be as\nprescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "67", "title": "Qualification of the Member of Appellate Tribunal: (1) A person who", "content": "has the knowledge in information technology and who is or who has already\nbeen or who is qualified to be a judge in the Appellate Court shall be eligible to\nbe a law member of the Appellate Tribunal.\n(2) A Nepali citizen who holds at least master degree in computer\nscience or information technology and who has at least five years experience in\nthe electronic transaction, information technology or electronic communication\nshall be eligible to be an information technology member of the Tribunal.\n(3) A Nepali citizen who holds at least master degree in management\nor commerce and who has specialization in the field of electronic transactions\nand who has at least five years experience in the relevant field, shall be eligible\nto be a commerce member.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "68", "title": "Terms of Office, Remuneration and Terms & Conditions of the", "content": "service of the Member of Appellate Tribunal: (1) The term of office of\nthe member of the Appellate Tribunal shall be of five years and he/she shall be\neligible for reappointment.\n(2) Remuneration and other terms and conditions of the services of\nthe members of the Appellate Tribunal shall as prescribed.\n32\n(3) A member of the Appellate Tribunal shall, before assuming\nhis/her office after appointment, take the oath of his/her office and secrecy\nbefore the Chief Justice of the Supreme Court.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "69", "title": "Conditions of Vacancy of Office and filling up of such Vacancy: (1)", "content": "Office of a Member of Appellate Tribunal shall be fallen vacant in the\nfollowing circumstances:\n(a) On expiry of terms of office,\n(b) On attainment of sixty three years age,\n(c) On death,\n(d) If one tenders resignation\n(e) If one is convicted by a court on any criminal offence involving\nmoral turpitude, and,\n(f) If it is proved that one has misbehavior or has become\nincompetent to perform one's duty, while making an inquiry by\nGovernment of Nepal on the charge that one has misbehavior\nagainst one's office or has become incompetent to perform one's\nduty.\nProvided that, a member of the Appellate Tribunal charged under this\nClause shall be given a reasonable opportunity to defense his/her case.\n(2) Notwithstanding anything contained in Clause (f), if the law\nmember of the Tribunal is a sitting judge, while making such an inquiry, it shall\nbe done in accordance with the prevailing law concerning his/her terms of\nservice.\n(3) The procedure of inquiry, for the purpose of Clause (f) of Sub-\nsection (1), shall as prescribed.\n(4) Government of Nepal shall, in case of vacancy of the office of\nany member of Tribunal under Sub-section (1), fulfill such vacancy from\n33\namongst the persons who are qualified under section 67 for remaining term of\noffice of such a member.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "70", "title": "Staff of the Appellate Tribunal: (1) Government of Nepal shall make", "content": "available necessary staff to Appellate Tribunal to perform its functions.\n(2) Other provisions regarding the staff of the Appellate Tribunal\nshall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "71", "title": "Procedures to be followed by the Appellate Tribunal: The Tribunal", "content": "shall, while initiating proceedings and adjudicating the appeal filed before it,\nshall follow the procedures as prescribed.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-12", "title": "Chapter-12", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "72", "title": "Provision may be made by an Agreement: The parties involved to the", "content": "work for creating, transmitting, receiving, storage or for processing through\nany other means, of any electronic record may make the provision by an\nagreement, not to apply any or all provisions of the Chapter 3 or to alter some\nof the provisions referred to in the said Chapter in course of their business and\nmay make the provisions to regulate their activities accordingly.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "73", "title": "Government of Nepal may issue Directives: Government of Nepal may, in", "content": "regard to the implementation of this Act, issue necessary directives to the\nController or Certifying Authority, and in such a case, it shall be a duty of the\nController or Certifying Authority, as the case may be, to comply with such\ndirectives.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "74", "title": "Time Limitation to file a Complaint: If a violation of this Act or Rules", "content": "framed hereunder has been occurred or if any act deemed to be an offence\nunder this Act has been committed, first information report in regard to such a\nviolation or an offence shall have to file within thirty five days of the\ninformation on which such a violation has been occurred or an offence has\nbeen committed.\n34", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "75", "title": "Government of Nepal to be a Plaintiff: (1) Any case deemed to be an", "content": "offence under this Act shall be initiated by Government of Nepal as plaintiff\nand such a case shall be deemed have been included in Schedule 1 of the\nGovernment Cases Act, 1992 (2049).\n(2) While conducting investigation of a case under Sub-section (1),\nthe police has to take assistance of the Controller or other concerned expert, as\nthe case may be.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "76", "title": "Compensation to be Recovered: If any loss or damage has been caused to", "content": "any person by the reason of offence committed under this Act, the\ncompensation of such loss or damage shall also be recovered from the offender.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "77", "title": "This Act shall not Apply: (1) Notwithstanding anything contained elsewhere", "content": "in this Act, this Act shall not be applied in the following matters:\n(a) Negotiable Instruments as referred to in the Negotiable\nInstruments Act, 2034 (1977).\n(b) Deed of will, deed of mortgage, bond, deed of conveyance,\npartition or any such deed related with transfer of the title in any\nimmovable property,\n(c) Any other document which demonstrates title or ownership in\nany immovable property,\n(d) Power of Attorney, statement of claim, statement of defense or\nany such other documents as may be used in courts proceedings,\n(e) Statement of claim, counter-claim, statement of defense or any\nsuch other document as may be submitted in writing in the\nproceedings of any Arbitration,\n(f) Documents as prescribed by the prevailing law that requires not\nto retain in electronic form.\n35\n(2) Notwithstanding anything contained in Sub-section (1)\nGovernment of Nepal may, by notification in the Nepal Gazette, alter the\ndocuments referred to in Sub-section (1).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "78", "title": "Power to Frame Rules: Government of Nepal may in order to fulfill the", "content": "objective of this Act, frame necessary Rules.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "79", "title": "To Frame and Enforce the Directives: Government of Nepal may, in", "content": "order to achieve the objective of this Act, frame and enforce necessary\ndirectives, subject to this Act and Rules framed hereunder.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "80", "title": "Effect of inoperativeness of The Electronic Transactions Ordinance,", "content": "2063 (2008): With the Electronic Transactions Ordinance, 2063 (2008) being\ninoperative, unless a different intention appears, the inoperativeness shall not,\n(a) Revive anything not prevailing or existing at the time, at which\nthe Ordinance became inoperative,\n(b) Affect the matter in operation as per the Ordinance or anything\nduly done or any punishment suffered there under,\n(c) Affect any right, privilege, obligation or liability acquired,\naccrued or incurred under the Ordinance,\n(d) Affect any penalty, punishment or forfeiture incurred under the\nOrdinance,\n(e) Affect any action or remedy made or taken in respect of any such\nright, privilege, obligation, liability, penalty or punishment as\naforesaid; and any such legal proceeding or remedy may be\ninstituted, continued or enforced as if the Ordinance were in\nforce.\n36", "children": []}]}]$CODExbe997d7b04$::jsonb,$CODEx40ee5763c9$Electronic Transaction Act 2063.pdf$CODEx40ee5763c9$) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, original_title=EXCLUDED.original_title, document_type=EXCLUDED.document_type, year_bs=EXCLUDED.year_bs, year_ad=EXCLUDED.year_ad, total_pages=EXCLUDED.total_pages, nodes=EXCLUDED.nodes, source_filename=EXCLUDED.source_filename;
